import { Controller, Get, Post, Put, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const USE_STATUSES = ['사용', '미사용'];

function toInt(v: unknown): number | null {
  if (typeof v === 'number') {
    return Number.isInteger(v) ? v : null;
  }
  if (typeof v === 'string' && /^-?\d+$/.test(v.trim())) {
    return Number(v.trim());
  }
  return null;
}

function invalid(message: string): ApiError {
  return new ApiError(400, 'VALIDATION_FAILED', message);
}

function categoryOf(v: unknown): string {
  if (typeof v !== 'string' || v.trim() === '' || v.length > 50) {
    throw invalid('급여 구분은 50자 이내로 입력해 주세요.');
  }
  return v;
}

function accountItemOf(v: unknown): number {
  const n = toInt(v);
  if (n === null) {
    throw invalid('계정과목 ID는 숫자여야 합니다.');
  }
  return n;
}

function useStatusOf(v: unknown): string {
  if (typeof v !== 'string' || !USE_STATUSES.includes(v)) {
    throw invalid('사용 여부는 사용 또는 미사용이어야 합니다.');
  }
  return v;
}

@Controller('api/v1')
export class FnSfr02004Controller {
  @Get('/payroll-account-settings')
  async listPayrollAccountSettings(@Req() req: Request) {
    const user = currentUser(req);
    user.require('급여 담당자');
    const query = checks.queryOf(req.query);
    const page = query['page'] === undefined || query['page'] === '' ? 0 : toInt(query['page']);
    const sizeRaw = query['size'] === undefined || query['size'] === '' ? DEFAULT_SIZE : toInt(query['size']);
    if (page === null || page < 0 || sizeRaw === null || sizeRaw < 1) {
      throw invalid('page 또는 size 값이 올바르지 않습니다.');
    }
    const size = Math.min(sizeRaw, MAX_SIZE);
    const category = typeof query['payrollCategory'] === 'string' && query['payrollCategory'] !== '' ? query['payrollCategory'] : null;
    return transaction(async (db) => {
      const params = { category, size, offset: page * size };
      const items = await db.query(
        `SELECT s.payroll_account_setting_id AS "payrollAccountSettingId",
                s.payroll_category AS "payrollCategory",
                s.account_item_id AS "accountItemId",
                a.account_code AS "accountCode",
                a.account_name AS "accountName",
                s.use_status AS "useStatus"
           FROM payroll_account_setting s
           JOIN account_item a ON a.account_item_id = s.account_item_id
          WHERE (CAST(:category AS text) IS NULL OR s.payroll_category = CAST(:category AS text))
          ORDER BY s.payroll_account_setting_id
          LIMIT :size OFFSET :offset`,
        params,
      );
      const counts = await db.query(
        `SELECT COUNT(*) AS "total"
           FROM payroll_account_setting s
          WHERE (CAST(:category AS text) IS NULL OR s.payroll_category = CAST(:category AS text))`,
        { category },
      );
      return { items, page, size, total: Number(counts[0]['total']) };
    });
  }

  @Post('/payroll-account-settings')
  @HttpCode(200)
  async createPayrollAccountSetting(@Req() req: Request) {
    const user = currentUser(req);
    user.require('급여 담당자');
    const data = checks.inputOf(req.body);
    const payrollCategory = categoryOf(data['payrollCategory']);
    const accountItemId = accountItemOf(data['accountItemId']);
    const useStatus = useStatusOf(data['useStatus']);
    return transaction(async (db) => {
      const accounts = await db.query(
        'SELECT account_item_id FROM account_item WHERE account_item_id = CAST(:accountItemId AS bigint)',
        { accountItemId },
      );
      if (accounts.length === 0) {
        throw new ApiError(404, 'ACCOUNT_ITEM_NOT_FOUND', '등록되지 않은 계정과목입니다.');
      }
      const same = await db.query(
        `SELECT payroll_account_setting_id FROM payroll_account_setting
          WHERE payroll_category = :payrollCategory
            AND (account_item_id = CAST(:accountItemId AS bigint) OR (:useStatus = '사용' AND use_status = '사용'))`,
        { payrollCategory, accountItemId, useStatus },
      );
      if (same.length > 0) {
        throw new ApiError(409, 'PAYROLL_ACCOUNT_SETTING_DUPLICATED', '동일 급여 구분에 설정이 이미 있습니다. 기존 설정을 변경해 주세요.');
      }
      const rows = await db.query(
        `INSERT INTO payroll_account_setting (account_item_id, payroll_category, use_status, created_at, updated_at)
         VALUES (CAST(:accountItemId AS bigint), :payrollCategory, :useStatus, now(), now())
         RETURNING payroll_account_setting_id AS "payrollAccountSettingId"`,
        { accountItemId, payrollCategory, useStatus },
      );
      return { payrollAccountSettingId: Number(rows[0]['payrollAccountSettingId']) };
    });
  }

  @Put('/payroll-account-settings/:payrollAccountSettingId')
  async updatePayrollAccountSetting(@Req() req: Request) {
    const user = currentUser(req);
    user.require('급여 담당자');
    const settingId = toInt(req.params['payrollAccountSettingId']);
    if (settingId === null) {
      throw invalid('설정 ID가 올바르지 않습니다.');
    }
    const data = checks.inputOf(req.body);
    const accountItemId = accountItemOf(data['accountItemId']);
    const useStatus = useStatusOf(data['useStatus']);
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT payroll_category AS "payrollCategory" FROM payroll_account_setting WHERE payroll_account_setting_id = CAST(:settingId AS bigint)',
        { settingId },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'PAYROLL_ACCOUNT_SETTING_NOT_FOUND', '급여 전표 계정과목 설정이 없습니다.');
      }
      const payrollCategory = String(found[0]['payrollCategory']);
      const accounts = await db.query(
        'SELECT account_item_id FROM account_item WHERE account_item_id = CAST(:accountItemId AS bigint)',
        { accountItemId },
      );
      if (accounts.length === 0) {
        throw new ApiError(404, 'PAYROLL_ACCOUNT_SETTING_NOT_FOUND', '등록되지 않은 계정과목입니다.');
      }
      const same = await db.query(
        `SELECT payroll_account_setting_id FROM payroll_account_setting
          WHERE payroll_category = :payrollCategory
            AND payroll_account_setting_id <> CAST(:settingId AS bigint)
            AND (account_item_id = CAST(:accountItemId AS bigint) OR (:useStatus = '사용' AND use_status = '사용'))`,
        { payrollCategory, settingId, accountItemId, useStatus },
      );
      if (same.length > 0) {
        throw new ApiError(409, 'PAYROLL_ACCOUNT_SETTING_DUPLICATED', '동일 급여 구분에 설정이 이미 있습니다. 기존 설정을 변경해 주세요.');
      }
      await db.execute(
        `UPDATE payroll_account_setting
            SET account_item_id = CAST(:accountItemId AS bigint),
                use_status = :useStatus,
                updated_at = now()
          WHERE payroll_account_setting_id = CAST(:settingId AS bigint)`,
        { accountItemId, useStatus, settingId },
      );
      return { payrollAccountSettingId: settingId };
    });
  }
}

