import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Tiles,
  Form,
  Field,
  TextInput,
  Select,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Page, Row } from '../kit';

const SIZE = 20;

type DrawerState = { mode: 'create' } | { mode: 'edit'; row: Row } | null;

export default function FnSfr02004Page({ role, notify }: PageProps) {
  const [categoryInput, setCategoryInput] = useState('');
  const [category, setCategory] = useState('');
  const [page, setPage] = useState(0);
  const [drawer, setDrawer] = useState<DrawerState>(null);
  const [formCategory, setFormCategory] = useState('');
  const [formAccount, setFormAccount] = useState<number | string>('');
  const [formUse, setFormUse] = useState('사용');

  const { data, error, reload } = useData<Page>(
    () => call<Page>('GET', '/payroll-account-settings', role, undefined, { payrollCategory: category, page, size: SIZE }),
    [category, page, role],
  );

  const rows = data ? data.items : [];
  const activeCount = rows.filter((r) => r['useStatus'] === '사용').length;

  function openCreate() {
    setFormCategory('');
    setFormAccount('');
    setFormUse('사용');
    setDrawer({ mode: 'create' });
  }

  function openEdit(row: Row) {
    setFormCategory(String(row['payrollCategory'] ?? ''));
    setFormAccount(row['accountItemId'] as number);
    setFormUse(String(row['useStatus'] ?? '사용'));
    setDrawer({ mode: 'edit', row });
  }

  async function submit() {
    if (!drawer) {
      return;
    }
    if (drawer.mode === 'create' && formCategory.trim() === '') {
      throw new Error('급여 구분을 입력해 주세요.');
    }
    if (formAccount === '') {
      throw new Error('계정과목을 선택해 주세요.');
    }
    if (formUse === '') {
      throw new Error('사용 여부를 선택해 주세요.');
    }
    if (drawer.mode === 'create') {
      await call('POST', '/payroll-account-settings', role, {
        payrollCategory: formCategory,
        accountItemId: formAccount,
        useStatus: formUse,
      });
      notify('등록했습니다.');
    } else {
      await call('PUT', '/payroll-account-settings/' + String(drawer.row['payrollAccountSettingId']), role, {
        accountItemId: formAccount,
        useStatus: formUse,
      });
      notify('수정했습니다.');
    }
    setDrawer(null);
    reload();
  }

  return (
    <div className="bento">
      <section className="box span-8">
        <h2>계정과목 설정</h2>
        <Filters
          onSearch={() => {
            setPage(0);
            setCategory(categoryInput);
          }}
          onReset={() => {
            setCategoryInput('');
            setCategory('');
            setPage(0);
          }}
        >
          <Field label="급여 구분">
            <TextInput value={categoryInput} onChange={setCategoryInput} />
          </Field>
        </Filters>
        <Band total={data ? data.total : 0}>
          <button type="button" onClick={openCreate}>설정 등록</button>
        </Band>
        {error ? <ErrorText text={error} /> : null}
        <DataTable
          rows={rows}
          empty="등록된 설정이 없습니다."
          columns={[
            { key: 'payrollCategory', label: '급여 구분' },
            { key: 'accountItemId', label: '계정과목 ID', render: (r) => <RefName table="account_item" role={role} value={r['accountItemId']} /> },
            { key: 'accountCode', label: '계정과목 코드' },
            { key: 'accountName', label: '계정과목 명칭' },
            { key: 'useStatus', label: '사용 여부', render: (r) => <Badge value={r['useStatus']} /> },
            {
              key: 'edit',
              label: '처리',
              render: (r) => <button type="button" onClick={() => openEdit(r)}>수정</button>,
            },
          ]}
        />
        <Pager page={page} size={SIZE} total={data ? data.total : 0} onPage={setPage} />
      </section>
      <section className="box span-4">
        <h2>설정 현황</h2>
        <Tiles
          items={[
            ['전체 설정', <Num value={data ? data.total : 0} />],
            ['이 쪽 사용 중', <Num value={activeCount} />],
          ]}
        />
      </section>
      {drawer ? (
        <Drawer title={drawer.mode === 'create' ? '계정과목 설정 등록' : '계정과목 설정 수정'} onClose={() => setDrawer(null)}>
          <Form onSubmit={submit} submit={drawer.mode === 'create' ? '등록' : '수정'}>
            <Field label="급여 구분" required>
              {drawer.mode === 'create' ? (
                <TextInput value={formCategory} onChange={setFormCategory} />
              ) : (
                <span>{formCategory}</span>
              )}
            </Field>
            <Field label="계정과목 ID" required>
              <LookupSelect table="account_item" role={role} value={formAccount} onChange={setFormAccount} />
            </Field>
            <Field label="사용 여부" required>
              <Select value={formUse} onChange={setFormUse} options={[['사용', '사용'], ['미사용', '미사용']]} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
